<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role('cashier');
$title='Pembayaran';
if(isset($_GET['pay'])){$pdo->prepare("UPDATE transactions SET payment_status='paid' WHERE id=?")->execute([(int)$_GET['pay']]);header('Location:/cashier/payment.php');exit;}
$rows=$pdo->query("SELECT t.*,c.name customer,v.plate_number FROM transactions t JOIN customers c ON c.id=t.customer_id JOIN vehicles v ON v.id=t.vehicle_id ORDER BY t.id DESC")->fetchAll();require __DIR__.'/../includes/header.php';?><h2>Pembayaran</h2><div class="card"><div class="card-body"><table class="table"><tr><th>Invoice</th><th>Pelanggan</th><th>Plat</th><th>Total</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['invoice_number'])?></td><td><?=e($r['customer'])?></td><td><?=e($r['plate_number'])?></td><td>Rp <?=number_format($r['total'],0,',','.')?></td><td><?=$r['payment_status']?></td><td><?php if($r['payment_status']==='unpaid'):?><a class="btn btn-sm btn-success" onclick="return confirm('Konfirmasi pembayaran?')" href="?pay=<?=$r['id']?>">Bayar</a><?php else:?><span class="badge bg-success">Lunas</span><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
